/** The Material 3 colour scheme derived from the semantic colours, so stock components fit the palette. */
fun KbColors.toColorScheme(dark: Boolean): ColorScheme =
    if (dark) {
        darkColorScheme(
            primary = primary,
            onPrimary = onPrimary,
            primaryContainer = primaryContainer,
            onPrimaryContainer = onPrimaryContainer,
            inversePrimary = link,
            secondary = textMuted,
            onSecondary = surface,
            secondaryContainer = surfaceSelected,
            onSecondaryContainer = text,
            tertiary = brand,
            onTertiary = surface,
            tertiaryContainer = dangerContainer,
            onTertiaryContainer = onDangerContainer,
            background = bg,
            onBackground = text,
            surface = surface,
            onSurface = text,
            surfaceVariant = surfaceSunken,
            onSurfaceVariant = textMuted,
            surfaceTint = primary,
            error = danger,
            onError = onDanger,
            errorContainer = dangerContainer,
            onErrorContainer = onDangerContainer,
            outline = borderStrong,
            outlineVariant = border,
            surfaceBright = surfaceRaised,
            surfaceDim = bg,
            surfaceContainerLowest = surface,
            surfaceContainerLow = surface,
            surfaceContainer = bg,
            surfaceContainerHigh = surfaceHover,
            surfaceContainerHighest = surfaceSunken,
        )
    } else {
        lightColorScheme(
            primary = primary,
            onPrimary = onPrimary,
            primaryContainer = primaryContainer,
            onPrimaryContainer = onPrimaryContainer,
            inversePrimary = link,
            secondary = textMuted,
            onSecondary = surface,
            secondaryContainer = surfaceSelected,
            onSecondaryContainer = text,
            tertiary = brand,
            onTertiary = surface,
            tertiaryContainer = dangerContainer,
            onTertiaryContainer = onDangerContainer,
            background = bg,
            onBackground = text,
            surface = surface,
            onSurface = text,
            surfaceVariant = surfaceSunken,
            onSurfaceVariant = textMuted,
            surfaceTint = primary,
            error = danger,
            onError = onDanger,
            errorContainer = dangerContainer,
            onErrorContainer = onDangerContainer,
            outline = borderStrong,
            outlineVariant = border,
            surfaceBright = surfaceRaised,
            surfaceDim = bg,
            surfaceContainerLowest = surface,
            surfaceContainerLow = surface,
            surfaceContainer = bg,
            surfaceContainerHigh = surfaceHover,
            surfaceContainerHighest = surfaceSunken,
        )
    }

/** Text styles (sp, so they follow the system font scale). Family-less: [kbTypography] applies the fonts. */
object KbType {
    /** Kanji literal on kanji cards and the kanji page. */
    val jpHero: TextStyle = TextStyle(fontSize = 80.sp, lineHeight = 88.sp, fontWeight = FontWeight(400), letterSpacing = 0.em)
    /** Review headword, dictionary headword. */
    val jpDisplay: TextStyle = TextStyle(fontSize = 40.sp, lineHeight = 52.sp, fontWeight = FontWeight(500), letterSpacing = 0.em)
    /** Big numbers: due count, streak, stats headline figures (tabular numerals). */
    val display: TextStyle = TextStyle(fontSize = 32.sp, lineHeight = 38.sp, fontWeight = FontWeight(600), letterSpacing = -0.01.em)
    /** Page titles. */
    val headline: TextStyle = TextStyle(fontSize = 26.sp, lineHeight = 34.sp, fontWeight = FontWeight(600), letterSpacing = -0.005.em)
    /** Section and card titles, dialog titles. */
    val title: TextStyle = TextStyle(fontSize = 20.sp, lineHeight = 28.sp, fontWeight = FontWeight(600), letterSpacing = 0.em)
    /** List-row primary line, table headings of panels. */
    val titleSm: TextStyle = TextStyle(fontSize = 17.sp, lineHeight = 25.sp, fontWeight = FontWeight(600), letterSpacing = 0.em)
    /** Japanese running text: example sentences, reader. Airy for kana. */
    val jpBody: TextStyle = TextStyle(fontSize = 18.sp, lineHeight = 34.sp, fontWeight = FontWeight(400), letterSpacing = 0.02.em)
    /** Kana readings under a headword. */
    val reading: TextStyle = TextStyle(fontSize = 18.sp, lineHeight = 29.sp, fontWeight = FontWeight(400), letterSpacing = 0.04.em)
    /** Glosses on the review back and the dictionary entry. */
    val bodyLg: TextStyle = TextStyle(fontSize = 17.sp, lineHeight = 29.sp, fontWeight = FontWeight(400), letterSpacing = 0.em)
    /** Default UI text. */
    val body: TextStyle = TextStyle(fontSize = 16.sp, lineHeight = 26.sp, fontWeight = FontWeight(400), letterSpacing = 0.em)
    /** Secondary lines, table cells. */
    val bodySm: TextStyle = TextStyle(fontSize = 14.sp, lineHeight = 22.sp, fontWeight = FontWeight(400), letterSpacing = 0.em)
    /** Buttons, tabs, chips, form labels. */
    val label: TextStyle = TextStyle(fontSize = 14.sp, lineHeight = 18.sp, fontWeight = FontWeight(500), letterSpacing = 0.01.em)
    /** Metadata, key hints, interval previews. The smallest size in the app. */
    val caption: TextStyle = TextStyle(fontSize = 12.sp, lineHeight = 17.sp, fontWeight = FontWeight(400), letterSpacing = 0.01.em)
    /** Uppercase section eyebrows (Latin only; never on Japanese). */
    val overline: TextStyle = TextStyle(fontSize = 12.sp, lineHeight = 17.sp, fontWeight = FontWeight(600), letterSpacing = 0.08.em)
    /** Furigana: base size × RUBY_SCALE, never below RUBY_MIN_SP. */
    const val RUBY_SCALE: Float = 0.6f
    const val RUBY_MIN_SP: Float = 12f
    const val RUBY_LINE_HEIGHT: Float = 2.2f
}

/** The family of each role (serif roles use the Mincho face). */
private val serifRoles: Set<String> = setOf("jpHero")

/** Material 3 typography from [KbType]. Pass the bundled Noto Sans JP / Noto Serif JP families (UI-APP). */
fun kbTypography(sans: FontFamily = FontFamily.Default, serif: FontFamily = FontFamily.Serif): Typography {
    fun f(role: String, s: TextStyle): TextStyle = s.copy(fontFamily = if (role in serifRoles) serif else sans)
    return Typography(
        displayLarge = f("jpHero", KbType.jpHero),
        displayMedium = f("jpDisplay", KbType.jpDisplay),
        displaySmall = f("display", KbType.display),
        headlineLarge = f("display", KbType.display),
        headlineMedium = f("headline", KbType.headline),
        headlineSmall = f("title", KbType.title),
        titleLarge = f("title", KbType.title),
        titleMedium = f("titleSm", KbType.titleSm),
        titleSmall = f("label", KbType.label),
        bodyLarge = f("bodyLg", KbType.bodyLg),
        bodyMedium = f("body", KbType.body),
        bodySmall = f("bodySm", KbType.bodySm),
        labelLarge = f("label", KbType.label),
        labelMedium = f("caption", KbType.caption),
        labelSmall = f("overline", KbType.overline),
    )
}

